import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, texture, uniform, mul, add, sin, time, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Color } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // Card dimensions (aspect ratio ~1.6 matching 512x320)
  const width = 2.4;
  const height = 1.5;

  // Colors from visual spec
  const inkColor = new Color('#16161d');
  const paperColor = new Color('#e8ecf2');
  const accentColor = new Color('#ff2a38');
  const surfaceColor = new Color('#0b0b10');

  // Geometry
  const geometry = new PlaneGeometry(width, height);

  // Fallback map uniform & material setup
  const textureUniform = uniform(null);
  const hasTexture = uniform(0);

  // TSL Shader logic for engineered gradient, subtle grain, and texture overlay
  const uvVal = uv();

  // Custom pseudo-random grain
  const grainSeed = mul(uvVal.x, uvVal.y).add(time.mul(0.05));
  const grain = fract(sin(grainSeed).mul(43758.5453)).mul(0.04);

  // Base background gradient: near-black surface (#0b0b10) to deep ink (#16161d)
  const baseGrad = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    uvVal.y
  );

  // Accent pin-stripe at the top edge of the card
  const topEdge = uvVal.y.gt(0.97);
  const finalBackground = mix(
    baseGrad.add(grain),
    vec3(accentColor.r, accentColor.g, accentColor.b),
    topEdge.select(1.0, 0.0)
  );

  // Optional Texture overlay blending logic
  const texColor = texture(textureUniform, uvVal);
  const colorNode = mix(
    finalBackground,
    texColor.rgb,
    hasTexture.mul(texColor.a)
  );

  const material = new MeshBasicNodeMaterial({
    colorNode: vec4(colorNode, 1)
  });

  const cardMesh = new Mesh(geometry, material);
  group.add(cardMesh);

  // Load Image Asset via context loader
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/orb-decor.png';
  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        textureUniform.value = tex;
        hasTexture.value = 1.0;
        material.needsUpdate = true;
      })
      .catch((err) => {
        console.warn('Failed loading image asset for journal card:', err);
      });
  }

  // Visual frame outline to ground the element (Machined metal look, paper/silver outline)
  const outlineGeo = new PlaneGeometry(width + 0.02, height + 0.02);
  const outlineMat = new MeshBasicNodeMaterial({
    colorNode: vec4(paperColor.r * 0.15, paperColor.g * 0.15, paperColor.b * 0.15, 1.0)
  });
  const outlineMesh = new Mesh(outlineGeo, outlineMat);
  outlineMesh.position.z = -0.005;
  group.add(outlineMesh);

  // Subtle entry animation
  group.scale.set(0.9, 0.9, 0.9);
  group.position.y -= 0.1;

  const tl = gsap.timeline({ defaults: { ease: 'power3.out', duration: 1.2 } });
  tl.to(group.scale, { x: 1, y: 1, z: 1 });
  tl.to(group.position, { y: 0 }, '<');
  timelines.push(tl);

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    outlineGeo.dispose();
    material.dispose();
    outlineMat.dispose();
    timelines.forEach((t) => t.kill());
  };

  return group;
}
